import { Controller, Get, Post, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 허용 인증기기 수 설정(auth_setting)이 없을 때 쓰는 기본값
const DEFAULT_ALLOWED_DEVICE_COUNT = 1;
// 가정: 반려 사유를 입력하지 않았을 때 저장하는 문구 (반려 시 reject_reason은 필수 컬럼 제약)
const DEFAULT_REJECT_REASON = '사유 없음';
const APPROVAL_STATUSES = ['신청', '승인', '반려'];

type Db = {
  query: (sql: string, params?: Record<string, unknown>) => Promise<any[]>;
  execute: (sql: string, params?: Record<string, unknown>) => Promise<number>;
};

function validation(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function idOf(value: unknown): string {
  if (typeof value !== 'string' || !/^\d+$/.test(value)) {
    throw validation('인증기기 ID 형식이 올바르지 않습니다.');
  }
  return value;
}

function textOf(value: unknown, label: string, max: number, required: boolean): string | null {
  if (value === undefined || value === null || value === '') {
    if (required) {
      throw validation(label + '을(를) 입력해 주세요.');
    }
    return null;
  }
  if (typeof value !== 'string') {
    throw validation(label + ' 형식이 올바르지 않습니다.');
  }
  if (value.length > max) {
    throw validation(label + '은(는) ' + max + '자 이하로 입력해 주세요.');
  }
  return value;
}

async function loadDevice(db: Db, id: string) {
  const rows = await db.query(
    'SELECT auth_device_id AS "authDeviceId", employee_id AS "employeeId", approval_status AS "approvalStatus", use_status AS "useStatus" FROM auth_device WHERE auth_device_id = CAST(:id AS bigint) FOR UPDATE',
    { id },
  );
  if (rows.length === 0) {
    throw new ApiError(404, 'AUTH_DEVICE_NOT_FOUND', '인증기기를 찾을 수 없습니다.');
  }
  return rows[0];
}

async function addHistory(db: Db, userId: string, id: string, type: string, content: string) {
  await db.execute(
    'INSERT INTO change_history (changer_id, target_type, target_id, change_type, changed_at, change_content, created_at, updated_at) VALUES (CAST(:userId AS bigint), \'auth_device\', CAST(:id AS bigint), :type, now(), :content, now(), now())',
    { userId, id, type, content },
  );
}

async function addNotification(db: Db, recipientId: unknown, id: string, title: string, content: string) {
  await db.execute(
    'INSERT INTO notification (recipient_id, channel, title, content, read_status, event_type, target_type, target_id, created_at, updated_at) VALUES (CAST(:recipientId AS bigint), \'포털\', :title, :content, \'안읽음\', \'AUTH_DEVICE\', \'auth_device\', CAST(:id AS bigint), now(), now())',
    { recipientId: String(recipientId), id, title, content },
  );
}

@Controller('api/v1')
export class FnSfr03703Controller {
  @Get('/auth-devices')
  async listAuthDevices(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자', '임직원');
    const query = checks.queryOf(req.query) as Record<string, unknown>;
    const approvalStatus = textOf(query['approvalStatus'], '승인 상태', 20, false);
    if (approvalStatus !== null && !APPROVAL_STATUSES.includes(approvalStatus)) {
      throw validation('승인 상태 값이 올바르지 않습니다.');
    }
    const employeeId = textOf(query['employeeId'] === undefined ? undefined : String(query['employeeId']), '임직원 ID', 20, false);
    if (employeeId !== null && !/^\d+$/.test(employeeId)) {
      throw validation('임직원 ID 형식이 올바르지 않습니다.');
    }
    const pageText = query['page'] === undefined || query['page'] === '' ? '0' : String(query['page']);
    const sizeText = query['size'] === undefined || query['size'] === '' ? '20' : String(query['size']);
    if (!/^\d+$/.test(pageText) || !/^\d+$/.test(sizeText)) {
      throw validation('쪽 번호와 크기 형식이 올바르지 않습니다.');
    }
    const page = Number(pageText);
    const size = Math.min(Math.max(Number(sizeText), 1), 200);
    return transaction(async (db: Db) => {
      const filter =
        ' WHERE (CAST(:approvalStatus AS varchar) IS NULL OR approval_status = CAST(:approvalStatus AS varchar))' +
        ' AND (CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint))';
      const items = await db.query(
        'SELECT auth_device_id AS "authDeviceId", employee_id AS "employeeId", device_name AS "deviceName", device_identifier AS "deviceIdentifier", approval_status AS "approvalStatus", use_status AS "useStatus" FROM auth_device' +
          filter +
          ' ORDER BY auth_device_id DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { approvalStatus, employeeId, size, offset: page * size },
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM auth_device' + filter,
        { approvalStatus, employeeId },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/auth-devices')
  @HttpCode(200)
  async createAuthDevice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    const deviceIdentifier = textOf(data['deviceIdentifier'], '기기 식별정보', 200, true);
    const deviceName = textOf(data['deviceName'], '기기명', 100, false);
    return transaction(async (db: Db) => {
      const duplicated = await db.query(
        'SELECT auth_device_id FROM auth_device WHERE employee_id = CAST(:userId AS bigint) AND device_identifier = :deviceIdentifier AND approval_status IN (\'신청\', \'승인\')',
        { userId: user.id, deviceIdentifier },
      );
      if (duplicated.length > 0) {
        throw new ApiError(409, 'AUTH_DEVICE_DUPLICATED', '이미 등록 요청된 기기입니다.');
      }
      const rows = await db.query(
        'INSERT INTO auth_device (employee_id, device_identifier, device_name, otp_enabled, approval_status, use_status, created_at, updated_at) VALUES (CAST(:userId AS bigint), :deviceIdentifier, :deviceName, true, \'신청\', \'미사용\', now(), now()) RETURNING auth_device_id AS "authDeviceId", approval_status AS "approvalStatus"',
        { userId: user.id, deviceIdentifier, deviceName },
      );
      const created = rows[0];
      await addHistory(db, user.id, String(created.authDeviceId), '등록 요청', '인증기기 등록을 요청했습니다.');
      return created;
    });
  }

  @Post('/auth-devices/:authDeviceId/approve')
  @HttpCode(200)
  async approveAuthDevice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const id = idOf(req.params['authDeviceId']);
    return transaction(async (db: Db) => {
      const device = await loadDevice(db, id);
      if (device.approvalStatus !== '신청') {
        throw new ApiError(409, 'AUTH_DEVICE_ALREADY_PROCESSED', '이미 승인·반려 처리된 요청입니다.');
      }
      const settings = await db.query(
        'SELECT allowed_device_count AS "allowedCount" FROM auth_setting WHERE employee_id = CAST(:employeeId AS bigint) OR employee_id IS NULL ORDER BY (employee_id IS NULL) ASC LIMIT 1',
        { employeeId: String(device.employeeId) },
      );
      const allowed = settings.length > 0 ? Number(settings[0].allowedCount) : DEFAULT_ALLOWED_DEVICE_COUNT;
      const approved = await db.query(
        'SELECT COUNT(*) AS "total" FROM auth_device WHERE employee_id = CAST(:employeeId AS bigint) AND approval_status = \'승인\'',
        { employeeId: String(device.employeeId) },
      );
      if (Number(approved[0].total) >= allowed) {
        throw new ApiError(422, 'ALLOWED_DEVICE_COUNT_EXCEEDED', '허용 인증기기 수(' + allowed + '대)를 초과하여 승인할 수 없습니다.');
      }
      const rows = await db.query(
        'UPDATE auth_device SET approval_status = \'승인\', use_status = \'사용\', approver_id = CAST(:userId AS bigint), processed_at = now(), updated_at = now() WHERE auth_device_id = CAST(:id AS bigint) RETURNING auth_device_id AS "authDeviceId", approval_status AS "approvalStatus"',
        { userId: user.id, id },
      );
      await addHistory(db, user.id, id, '승인', '인증기기를 승인했습니다.');
      await addNotification(db, device.employeeId, id, '인증기기 승인', '인증기기 등록 요청이 승인되었습니다.');
      return rows[0];
    });
  }

  @Post('/auth-devices/:authDeviceId/reject')
  @HttpCode(200)
  async rejectAuthDevice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const id = idOf(req.params['authDeviceId']);
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    const rejectReason = textOf(data['rejectReason'], '반려 사유', 500, false) ?? DEFAULT_REJECT_REASON;
    return transaction(async (db: Db) => {
      const device = await loadDevice(db, id);
      if (device.approvalStatus !== '신청') {
        throw new ApiError(409, 'AUTH_DEVICE_ALREADY_PROCESSED', '이미 승인·반려 처리된 요청입니다.');
      }
      const rows = await db.query(
        'UPDATE auth_device SET approval_status = \'반려\', reject_reason = :rejectReason, approver_id = CAST(:userId AS bigint), processed_at = now(), updated_at = now() WHERE auth_device_id = CAST(:id AS bigint) RETURNING auth_device_id AS "authDeviceId", approval_status AS "approvalStatus"',
        { userId: user.id, id, rejectReason },
      );
      await addHistory(db, user.id, id, '반려', '인증기기를 반려했습니다.');
      await addNotification(db, device.employeeId, id, '인증기기 반려', '인증기기 등록 요청이 반려되었습니다.');
      return rows[0];
    });
  }

  @Post('/auth-devices/:authDeviceId/deactivate')
  @HttpCode(200)
  async deactivateAuthDevice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const id = idOf(req.params['authDeviceId']);
    return transaction(async (db: Db) => {
      const device = await loadDevice(db, id);
      if (device.approvalStatus !== '승인') {
        throw new ApiError(409, 'AUTH_DEVICE_NOT_APPROVED', '승인되지 않은 기기입니다.');
      }
      // 가정: 사용중지 처리자와 처리 일시를 approver_id, processed_at에 기록한다
      const rows = await db.query(
        'UPDATE auth_device SET use_status = \'미사용\', approver_id = CAST(:userId AS bigint), processed_at = now(), updated_at = now() WHERE auth_device_id = CAST(:id AS bigint) RETURNING auth_device_id AS "authDeviceId", use_status AS "useStatus"',
        { userId: user.id, id },
      );
      await addHistory(db, user.id, id, '사용중지', '승인된 인증기기를 사용중지했습니다.');
      return rows[0];
    });
  }

  @Delete('/auth-devices/:authDeviceId')
  async deleteAuthDevice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const id = idOf(req.params['authDeviceId']);
    return transaction(async (db: Db) => {
      await loadDevice(db, id);
      await addHistory(db, user.id, id, '삭제', '인증기기를 삭제했습니다.');
      await db.execute(
        'DELETE FROM auth_device WHERE auth_device_id = CAST(:id AS bigint)',
        { id },
      );
      return {};
    });
  }
}

