import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

type Mode = 'create' | 'approve' | 'reject' | 'deactivate' | 'delete' | null;

const STATUS_OPTIONS: [string, string][] = [
  ['신청', '신청'],
  ['승인', '승인'],
  ['반려', '반려'],
];

export default function FnSfr03703Page({ role, notify }: PageProps) {
  const [approvalStatus, setApprovalStatus] = useState('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [mode, setMode] = useState<Mode>(null);
  const [deviceIdentifier, setDeviceIdentifier] = useState('');
  const [deviceName, setDeviceName] = useState('');
  const [rejectReason, setRejectReason] = useState('');

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/auth-devices', role, undefined, { ...applied, page, size: 20 }),
    [applied, page, role],
  );

  function search() {
    setPage(0);
    setApplied({ approvalStatus, employeeId });
  }

  function reset() {
    setApprovalStatus('');
    setEmployeeId('');
    setPage(0);
    setApplied({});
  }

  function closeDrawer() {
    setMode(null);
    setDeviceIdentifier('');
    setDeviceName('');
    setRejectReason('');
  }

  async function create() {
    if (!deviceIdentifier.trim()) {
      throw new Error('기기 식별정보를 입력해 주세요.');
    }
    await call('POST', '/auth-devices', role, { deviceIdentifier, deviceName });
    notify('인증기기 등록을 요청했습니다.');
    closeDrawer();
    reload();
  }

  async function approve() {
    await call('POST', `/auth-devices/${selected?.authDeviceId}/approve`, role, {});
    notify('인증기기를 승인했습니다.');
    closeDrawer();
    setSelected(null);
    reload();
  }

  async function reject() {
    await call('POST', `/auth-devices/${selected?.authDeviceId}/reject`, role, { rejectReason });
    notify('인증기기를 반려했습니다.');
    closeDrawer();
    setSelected(null);
    reload();
  }

  async function deactivate() {
    await call('POST', `/auth-devices/${selected?.authDeviceId}/deactivate`, role, {});
    notify('인증기기를 사용중지했습니다.');
    closeDrawer();
    setSelected(null);
    reload();
  }

  async function remove() {
    await call('DELETE', `/auth-devices/${selected?.authDeviceId}`, role);
    notify('인증기기를 삭제했습니다.');
    closeDrawer();
    setSelected(null);
    reload();
  }

  const drawer = (
    <>
      {mode === 'create' && (
        <Drawer title="인증기기 등록 요청" onClose={closeDrawer}>
          <Form onSubmit={create} submit="등록 요청">
            <Field label="기기 식별정보" required wide>
              <TextInput value={deviceIdentifier} onChange={setDeviceIdentifier} />
            </Field>
            <Field label="기기명" wide>
              <TextInput value={deviceName} onChange={setDeviceName} />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'approve' && (
        <Drawer title="인증기기 승인" onClose={closeDrawer}>
          <Form onSubmit={approve} submit="승인" note="승인하면 이 기기를 2차 인증 로그인에 사용할 수 있습니다. 허용 인증기기 수를 넘으면 승인되지 않습니다." />
        </Drawer>
      )}
      {mode === 'reject' && (
        <Drawer title="인증기기 반려" onClose={closeDrawer}>
          <Form onSubmit={reject} submit="반려" danger note="반려한 요청은 다시 처리할 수 없습니다.">
            <Field label="반려 사유" wide>
              <TextInput value={rejectReason} onChange={setRejectReason} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'deactivate' && (
        <Drawer title="인증기기 사용중지" onClose={closeDrawer}>
          <Form onSubmit={deactivate} submit="사용중지" danger note="사용중지하면 이 기기로는 로그인할 수 없습니다." />
        </Drawer>
      )}
      {mode === 'delete' && (
        <Drawer title="인증기기 삭제" onClose={closeDrawer}>
          <Form onSubmit={remove} submit="삭제" danger note="삭제한 인증기기는 되돌릴 수 없습니다." />
        </Drawer>
      )}
    </>
  );

  if (selected) {
    const status = String(selected.approvalStatus);
    const useStatus = String(selected.useStatus);
    return (
      <div className="doc">
        <button className="ghost" onClick={() => setSelected(null)}>
          목록으로 돌아가기
        </button>
        <section className="box">
          <h2>인증기기 정보</h2>
          <Pairs
            items={[
              ['기기명', String(selected.deviceName ?? '')],
              ['기기 식별정보', String(selected.deviceIdentifier ?? '')],
              ['임직원', <RefName table="employee" role={role} value={selected.employeeId} />],
              ['승인 상태', <Badge value={selected.approvalStatus} />],
              ['사용 여부', <Badge value={selected.useStatus} />],
            ]}
          />
        </section>
        <section className="box">
          <h2>처리</h2>
          {status === '신청' && (
            <>
              <button onClick={() => setMode('approve')}>승인</button>
              <button className="ghost" onClick={() => setMode('reject')}>
                반려
              </button>
            </>
          )}
          {status === '승인' && useStatus === '사용' && (
            <button className="ghost" onClick={() => setMode('deactivate')}>
              사용중지
            </button>
          )}
          <button className="ghost" onClick={() => setMode('delete')}>
            삭제
          </button>
        </section>
        {drawer}
      </div>
    );
  }

  return (
    <div className="doc">
      <h2>인증기기 승인·관리</h2>
      <Filters onSearch={search} onReset={reset}>
        <Field label="승인 상태">
          <Select value={approvalStatus} onChange={setApprovalStatus} options={STATUS_OPTIONS} placeholder="전체" />
        </Field>
        <Field label="임직원 ID">
          <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} placeholder="전체" />
        </Field>
      </Filters>
      <Band total={data?.total}>
        <button onClick={() => setMode('create')}>등록 요청</button>
      </Band>
      {error && <ErrorText text={error} />}
      <DataTable
        columns={[
          { key: 'deviceName', label: '기기명' },
          { key: 'deviceIdentifier', label: '기기 식별정보' },
          {
            key: 'employeeId',
            label: '임직원',
            render: (row) => <RefName table="employee" role={role} value={row.employeeId} />,
          },
          { key: 'approvalStatus', label: '승인 상태', render: (row) => <Badge value={row.approvalStatus} /> },
          { key: 'useStatus', label: '사용 여부', render: (row) => <Badge value={row.useStatus} /> },
        ]}
        rows={data?.items ?? []}
        onRowClick={(row) => setSelected(row)}
        empty={loading ? '불러오는 중입니다.' : '아직 등록한 인증기기가 없습니다. 등록 요청 버튼으로 기기를 등록해 주세요.'}
      />
      <Pager page={data?.page ?? 0} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPage} />
      {drawer}
    </div>
  );
}
